22	 * port its SPA was built against, the frozen seed snapshot it ships, and the
23	 * mutable store the server reads. The harness knows nothing app-specific: it
24	 * copies the declared snapshot over the declared store, runs the declared
25	 * command from the declared working directory, and waits for the declared
26	 * health probe. A future stateful application inherits this by declaring the
27	 * same fields; there is no branch on application identity anywhere in the
28	 * serving path.
29	 */
30	export type LiveBackendSpec = {
31		/** The application's own server executable, run from its lane root. */
32		command: string;
33		args: readonly string[];
34		/** The server's working directory, relative to the lane root. */
35		cwd?: string;
36		/** Extra environment the application's server reads, merged over the inherited environment. */
37		env?: Readonly<Record<string, string>>;
38		/**
39		 * The loopback port the server binds. It is fixed by the application because
40		 * its built SPA addresses it; the harness does not choose it, it serves it.
41		 */
42		port: number;
43		/**
44		 * The deterministic re-seed mechanism: the frozen seed snapshot and the
45		 * mutable store it is copied over before every pass. Both are lane-relative,
46		 * so the evidence names files rather than the machine.
47		 */
48		seed: { snapshot: string; store: string };
49		/**
50		 * Additional lane-relative file copies the application requires before its
51		 * server boots (for example a committed mock-config file the build expects).
52		 * Applied on every re-seed so a pass never inherits a previous pass's copy.
53		 */
54		prepare?: readonly { from: string; to: string }[];
55		/**
56		 * The readiness probe: an origin-relative path the server answers once it is
57		 * up, and the set of statuses that count as up. An auth-gated route that
58		 * answers 401 before any session exists is a server that is up, so the set is
59		 * declared rather than assumed to be 200.
60		 */
61		health: { path: string; okStatus: readonly number[] };
62		/** How long to wait for the health probe to pass before giving up. */
63		readyTimeoutMs?: number;
64	};
65	
66	/** A running live backend bound to a second bounded loopback origin. */
67	export type LiveBackendHandle = {
68		/** The `http://127.0.0.1:<port>` origin the application's server is bound to. */
69		origin: string;
70		/**
71		 * Restore the frozen seed and restart the server, so the next pass starts from
72		 * exactly the declared snapshot rather than inheriting the mutations the
73		 * previous pass made. A lowdb store is read at boot, so a re-seed is a
74		 * restart, not a live file swap.
75		 */
76		reseed(): Promise<void>;
77		/** Stop the server and release the loopback port. */
78		close(): Promise<void>;
79	};
