1056							interactions: run.interactions,
1057							assertions: run.assertions,
1058							routes: run.routes,
1059							trackedEvents: run.trackedEvents,
1060							witnessRecord: run.witnessRecord,
1061							cleanPage: run.cleanPage,
1062							offlineEvidence: run.offlineEvidence,
1063							servedStatic: run.servedStatic,
1064							observerFinalization: run.observerFinalization,
1065							successfulNonLoopback: run.successfulNonLoopback,
1066						}),
1067					)
1068			)
1069				throw new Error(`Witness real-app run differs: ${key}`);
1070			const pair = `${run.app}:${run.lane}`;
1071			const prior = semanticPasses.get(pair);
1072			if (prior !== undefined && prior !== run.semanticDigest)
1073				throw new Error(`Witness real-app repeated pass differs: ${pair}`);
1074			semanticPasses.set(pair, run.semanticDigest);
1075			for (const interaction of run.interactions) {
1076				gestures.add(interaction.kind);
1077			}
1078		}
1079		if (
1080			expected.size !== 0 ||
1081			[...gestures].sort().join(',') !== 'click,drag,hover,press,scroll,type'
1082		)
1083			throw new Error('Witness real-app interaction coverage differs');
1084		if (
1085			receipt.mutations?.length !== 2 ||
1086			receipt.mutations.some(
1087				(mutation) =>
1088					mutation.failure !== 'witness-semantic-assertion' ||
1089					mutation.intendedFailure !== true ||
1090					mutation.restoredByteIdentically !== true,
1091			) ||
1092			!receipt.mutations.some((mutation) => mutation.app === 'react-boilerplate') ||
1093			!receipt.mutations.some((mutation) => mutation.app === 'angular-realworld') ||
1094			receipt.killedByGoogleInventory?.transformEdits !== 3 ||
1095			receipt.locality?.mode !== 'offline' ||
1096			receipt.locality?.successfulNonLoopback !== 0 ||
1097			receipt.locality?.osWideIsolation !== false ||
1098			!receipt.nonclaims?.some((claim) => claim.includes('Drag is tested only')) ||
1099			receipt.integrity?.algorithm !== 'sha256' ||
1100			receipt.integrity.canonicalDigest !== witnessRealAppDigest(receipt)
1101		)
1102			throw new Error('Witness real-app receipt integrity or nonclaims differ');
1103		return receipt;
1104	}
