36		'versionless.witness-react-cypress-rwa.v1' as const;
37	export const WITNESS_REACT_CYPRESS_RWA_RECEIPT_PATH =
38		'evidence/runs/witness-react-cypress-rwa/receipt.json' as const;
39	export const REACT_CYPRESS_RWA_FIXTURE = 'react-cypress-rwa' as const;
40	export const REACT_CYPRESS_RWA_APPLICATION = 'cypress-realworld-app' as const;
41	
42	/**
43	 * The immutable cypress-realworld-app source identity, bound here so the
44	 * browser-proof receipt cannot silently rebind itself to a different revision or
45	 * archive. Every value is the application's own, taken from the pinned tag.
46	 */
47	export const REACT_CYPRESS_RWA_SOURCE = Object.freeze({
48		repository: 'https://github.com/cypress-io/cypress-realworld-app',
49		ref: 'refs/tags/v1.0.18',
50		revision: 'f6b5cf3a1799998dab71181eeed59460f8ada5f4',
51		archiveSha256: 'bd9319272dabc1e7263a0186e0aaae011f6219e6e106363d2c89426f9357b315',
52		frontendRoot: '.',
53		backendRoot: 'backend',
54		license: 'MIT',
55		react: '17.0.2',
56		reactScripts: '4.0.3',
57		typescript: '4.3.4',
58	});
59	
60	/**
61	 * The stable placeholder tokens the journey normalizes its minted, server-decided
62	 * and seed-derived values to. Each is generic — a token and where the value
63	 * comes from — and deliberately carries NO literal value: the created ids are
64	 * decided by the server at run time, and `{recipient-handle}` is captured from a
65	 * seed user the money-movement step pays, then normalized away so no seed
66	 * identity ever reaches the evidence.
67	 */
68	export const WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS = Object.freeze([
69		Object.freeze({
70			token: '{created-user-id}',
71			origin: 'the id the backend mints for the freshly signed-up account',
72		}),
73		Object.freeze({
74			token: '{created-account-id}',
75			origin: 'the id the backend mints for the account onboarding creates',
76		}),
77		Object.freeze({
78			token: '{created-transaction-id}',
79			origin: 'the id the backend mints for the payment the journey sends',
80		}),
81		Object.freeze({
82			token: '{recipient-handle}',
83			origin: 'a seed user the payment is sent to, captured from search and normalized so no seed identity reaches the evidence',
84		}),
85	]) as readonly WitnessJourneyPlaceholderDeclaration[];
86	
87	/**
88	 * The deterministic, NON-SEED account the journey signs up and acts as. It is a
89	 * corpus identity invented for the proof, not a credential from the seed
90	 * database, so recording it discloses nothing the application ships. The
91	 * redaction test enforces that this is the only identity literal in the
92	 * evidence and that no seed username, password or hash appears anywhere.
93	 */
94	export const WITNESS_REACT_CYPRESS_RWA_ACTOR = Object.freeze({
95		firstName: 'Versionless',
96		lastName: 'Prover',
97		username: 'versionless-rwa-actor',
98		password: 'versionless-rwa-passphrase',
99	});
100	
101	/**
102	 * Seed-database markers that must never appear in the evidence. The bcrypt
103	 * prefixes are the shape of every hashed password in the seed; `s3cret` is the
104	 * seed's shared plaintext password. Their absence is the redaction proof, and
105	 * the parser fails the run if any of them is found in a recorded string.
106	 */
107	export const WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS = Object.freeze([
108		's3cret',
109		'$2a$',
110		'$2b$',
111		'$2y$',
112	]);
113	
114	/**
115	 * The exact route sequence the journey drives, in order, after the initial
116	 * document load. Server-minted identifiers are normalized to their declared
117	 * placeholder tokens; every other segment is the literal path the application
118	 * navigated to. Pinning the whole sequence is what makes a dropped step or a
119	 * silently redirected route fail the run.
120	 */
121	export const WITNESS_REACT_CYPRESS_RWA_ROUTES = Object.freeze([
122		'/signup',
123		'/signin',
124		'/',
125		'/user/settings',
126		'/',
127		'/transaction/new',
128		'/transaction/{created-transaction-id}',
129		'/',
130		'/public',
131		'/contacts',
132		'/personal',
133		'/notifications',
134		'/',
135	]);
136	
137	/**
138	 * The declared loopback-backend category: every REST endpoint the journey
139	 * reaches on the application's own server, by method and origin-relative path.
140	 * A request to an endpoint outside this list fails the run. Paths that carry a
141	 * server-minted id use the placeholder token, so the category is comparable
142	 * across runs the same way the routes are.
143	 */
144	export const WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY = Object.freeze([
145		Object.freeze({ method: 'GET', path: '/checkAuth' }),
146		Object.freeze({ method: 'POST', path: '/users' }),
147		Object.freeze({ method: 'POST', path: '/login' }),
148		Object.freeze({ method: 'POST', path: '/logout' }),
149		Object.freeze({ method: 'GET', path: '/users' }),
150		Object.freeze({ method: 'PATCH', path: '/users/{created-user-id}' }),
151		Object.freeze({ method: 'GET', path: '/users/search' }),
152		Object.freeze({ method: 'POST', path: '/bankAccounts' }),
153		Object.freeze({ method: 'GET', path: '/bankAccounts' }),
154		Object.freeze({ method: 'POST', path: '/transactions' }),
155		Object.freeze({ method: 'GET', path: '/transactions' }),
156		Object.freeze({ method: 'GET', path: '/transactions/public' }),
157		Object.freeze({ method: 'GET', path: '/transactions/contacts' }),
158		Object.freeze({ method: 'GET', path: '/transactions/{created-transaction-id}' }),
159		Object.freeze({ method: 'GET', path: '/notifications' }),
160	]);
161	
162	export type WitnessReactCypressRwaSource = typeof REACT_CYPRESS_RWA_SOURCE;
163	
164	/** The SPA byte inventory for a live-backend run: scoped to the frontend dist only. */
165	export type WitnessReactCypressRwaServedStatic = {
166		transport: 'isolated-bounded-loopback-production-static';
167		documentFallback: 'index-only';
168		missingAssets: '404';
169		traversal: 'rejected';
170		inventory: { files: number; beforeSha256: string; afterSha256: string };
171		application: { path: 'index.html'; beforeSha256: string; afterSha256: string };
172		byteIdentical: true;
173		hmrControls: false;
174		liveBackend: WitnessLiveBackendServed;
175	};
176	
177	export type WitnessReactCypressRwaRun = {
178		app: typeof REACT_CYPRESS_RWA_APPLICATION;
179		framework: 'react';
180		lane: 'baseline' | 'migrated';
181		pass: 1 | 2;
182		result: 'pass';
183		interactions: Array<{ kind: WitnessGesture; selector: string }>;
184		assertions: string[];
185		routes: string[];
186		trackedEvents: string[];
187		witnessRecord: {
188			interactions: Array<{ kind: WitnessGesture; selector: string }>;
189			navigationPaths: string[];
190			trackedEventCounts: Record<string, number>;
191			consoleErrors: number;
192			pageErrors: number;
193			failedRequests: number;
194		};
195		cleanPage: true;
196		servedStatic: WitnessReactCypressRwaServedStatic;
197		loopbackBackend: WitnessLoopbackBackendInventory;
198		placeholders: readonly WitnessJourneyPlaceholderDeclaration[];
199		successfulNonLoopback: 0;
200		semanticDigest: string;
201		behaviorDigest: string;
202	};
203	
204	export type WitnessReactCypressRwaMutation = {
205		failure: 'witness-semantic-assertion';
206		intendedFailure: true;
207		lane: 'migrated';
208		seam: string;
209		path: string;
210		offset: number;
211		beforeSha256: string;
212		mutatedSha256: string;
213		afterRestoreSha256: string;
214		restoredByteIdentically: true;
215		restoredRun: 'pass';
216		restoredBehaviorDigest: string;
217	};
218	
219	export type WitnessReactCypressRwaReceipt = {
220		schemaVersion: typeof WITNESS_REACT_CYPRESS_RWA_SCHEMA;
221		result: 'pass';
222		fixture: typeof REACT_CYPRESS_RWA_FIXTURE;
223		application: typeof REACT_CYPRESS_RWA_APPLICATION;
224		framework: 'react';
225		source: WitnessReactCypressRwaSource;
226		provenance: Record<string, unknown>;
227		canonicalReceipt: { path: string; canonicalDigest: string; sha256: string };
228		runs: WitnessReactCypressRwaRun[];
229		mutation: WitnessReactCypressRwaMutation;
230		placeholders: readonly WitnessJourneyPlaceholderDeclaration[];
231		backendCategory: readonly { method: string; path: string }[];
232		determinism: {
233			reseededFromSnapshotBeforeEachPass: true;
234			mintedValuesPlaceholdered: true;
235			rule: typeof WITNESS_JOURNEY_PLACEHOLDER_RULE;
236		};
237		redaction: {
238			policy: 'no-seed-usernames-passwords-or-pii';
239			forbiddenMarkers: readonly string[];
240			actorIsNonSeedCorpusIdentity: true;
241		};
242		locality: {
243			mode: 'live-loopback-backend';
244			successfulNonLoopback: 0;
245			osWideIsolation: false;
246			rule: typeof WITNESS_LOOPBACK_BACKEND_RULE;
247		};
248		nonclaims: string[];
249		integrity: { algorithm: 'sha256'; canonicalDigest: string };
250	};
251	
252	const exact = (left: unknown, right: unknown): boolean =>
253		canonicalize(left) === canonicalize(right);
254	
255	function sha256Digest(value: unknown): value is string {
256		return typeof value === 'string' && value.length === 64;
257	}
258	
259	/**
260	 * The raw run digest: the whole run except the fields that identify a pass. Two
261	 * passes of the same lane re-seed to the same state and normalize the same
262	 * minted values, so this must be identical across a lane's passes.
263	 */
264	export function witnessReactCypressRwaRawDigest(run: WitnessReactCypressRwaRun): string {
265		const { pass: _pass, result: _result, semanticDigest: _semanticDigest, ...raw } = run;
266		const withoutBehavior = { ...raw } as Record<string, unknown>;
267		delete withoutBehavior.behaviorDigest;
268		return sha256(canonicalize(withoutBehavior));
269	}
270	
271	/**
272	 * The lane-independent behavior projection.
273	 *
274	 * Production SPA bytes are lane-specific by construction, so the byte inventory
275	 * stays in the run record and out of this digest; what remains is what both
276	 * lanes must share — the same journey, the same routes, the same backend
277	 * category shape, the same clean page. The loopback-backend inventory's admitted
278	 * total and category participate; the exact per-status observations do not,
279	 * because a lane's server build may answer a poll a different number of times.
280	 */
281	export function witnessReactCypressRwaBehaviorDigest(run: WitnessReactCypressRwaRun): string {
282		return sha256(
283			canonicalize({
284				app: run.app,
285				framework: run.framework,
286				interactions: run.interactions,
287				assertions: run.assertions,
288				routes: run.routes,
289				trackedEvents: run.trackedEvents,
290				witnessRecord: run.witnessRecord,
291				cleanPage: run.cleanPage,
292				servedStaticPolicy: {
293					transport: run.servedStatic.transport,
294					documentFallback: run.servedStatic.documentFallback,
295					missingAssets: run.servedStatic.missingAssets,
296					traversal: run.servedStatic.traversal,
297					byteIdentical: run.servedStatic.byteIdentical,
298					hmrControls: run.servedStatic.hmrControls,
299					liveBackend: run.servedStatic.liveBackend,
300				},
301				loopbackBackendPolicy: {
302					policy: run.loopbackBackend.policy,
303					backend: run.loopbackBackend.backend,
304					category: run.loopbackBackend.category,
305					outsideCategory: run.loopbackBackend.outsideCategory,
306					admitted: run.loopbackBackend.admitted,
307					successfulNonLoopback: run.loopbackBackend.successfulNonLoopback,
308				},
309				placeholders: run.placeholders,
310				successfulNonLoopback: run.successfulNonLoopback,
311			}),
312		);
313	}
314	
315	export function witnessReactCypressRwaDigest(receipt: WitnessReactCypressRwaReceipt): string {
316		const copy = structuredClone(receipt);
317		copy.integrity.canonicalDigest = '';
318		return sha256(canonicalize(copy));
319	}
320	
321	/**
322	 * Every string reachable in a value, so the redaction check can assert no seed
323	 * marker appears anywhere in the recorded evidence rather than in a hand-picked
324	 * subset of fields.
325	 */
326	function collectStrings(value: unknown, into: string[]): void {
327		if (typeof value === 'string') into.push(value);
328		else if (Array.isArray(value)) for (const item of value) collectStrings(item, into);
329		else if (value !== null && typeof value === 'object')
330			for (const item of Object.values(value)) collectStrings(item, into);
331	}
332	
333	function assertRedaction(run: WitnessReactCypressRwaRun, label: string): void {
334		const strings: string[] = [];
335		collectStrings(run, strings);
336		for (const text of strings)
337			for (const marker of WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS)
338				if (text.includes(marker))
339					throw new Error(`Cypress RWA Witness redaction leaked a seed marker: ${label}`);
340	}
341	
342	function assertServedStatic(served: WitnessReactCypressRwaServedStatic, label: string): void {
343		if (
344			served.transport !== 'isolated-bounded-loopback-production-static' ||
345			served.documentFallback !== 'index-only' ||
346			served.missingAssets !== '404' ||
347			served.traversal !== 'rejected' ||
348			!Number.isInteger(served.inventory?.files) ||
349			served.inventory.files < 1 ||
350			!sha256Digest(served.inventory.beforeSha256) ||
351			served.inventory.beforeSha256 !== served.inventory.afterSha256 ||
352			served.application?.path !== 'index.html' ||
353			!sha256Digest(served.application.beforeSha256) ||
354			served.application.beforeSha256 !== served.application.afterSha256 ||
355			served.byteIdentical !== true ||
356			served.hmrControls !== false ||
357			served.liveBackend?.backend !== 'live-loopback' ||
358			served.liveBackend.byteInventoryScope !== 'frontend-spa-dist' ||
359			served.liveBackend.rule !== WITNESS_LIVE_BACKEND_SERVED_RULE
360		)
361			throw new Error(`Cypress RWA Witness served-static differs: ${label}`);
362	}
363	
364	function assertLoopbackBackend(inventory: WitnessLoopbackBackendInventory, label: string): void {
365		if (
366			inventory?.policy !== 'live-first-party-loopback-backend' ||
367			inventory.backend !== 'live-loopback' ||
368			inventory.rule !== WITNESS_LOOPBACK_BACKEND_RULE ||
369			inventory.successfulNonLoopback !== 0 ||
370			!exact(inventory.outsideCategory, []) ||
371			!exact(inventory.category, WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY) ||
372			!Array.isArray(inventory.observed) ||
373			inventory.observed.length === 0 ||
374			inventory.admitted !== inventory.observed.reduce((sum, entry) => sum + entry.requests, 0)
375		)
376			throw new Error(`Cypress RWA Witness loopback-backend inventory differs: ${label}`);
377		const declared = new Set(
378			WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY.map((entry) => `${entry.method} ${entry.path}`),
379		);
380		for (const observation of inventory.observed)
381			if (!declared.has(`${observation.method} ${observation.path}`))
382				throw new Error(`Cypress RWA Witness backend observation is undeclared: ${label}`);
383	}
384	
385	export function parseWitnessReactCypressRwaReceipt(value: unknown): WitnessReactCypressRwaReceipt {
386		if (value === null || typeof value !== 'object' || Array.isArray(value))
387			throw new Error('Cypress RWA Witness receipt must be an object');
388		const receipt = value as WitnessReactCypressRwaReceipt;
389		const expectedRuns = new Set(['baseline:1', 'baseline:2', 'migrated:1', 'migrated:2']);
390		const behaviors = new Set<string>();
391		const semanticByLane = new Map<string, string>();
392		if (
393			receipt.schemaVersion !== WITNESS_REACT_CYPRESS_RWA_SCHEMA ||
394			receipt.result !== 'pass' ||
395			receipt.fixture !== REACT_CYPRESS_RWA_FIXTURE ||
396			receipt.application !== REACT_CYPRESS_RWA_APPLICATION ||
397			receipt.framework !== 'react' ||
398			!exact(receipt.source, REACT_CYPRESS_RWA_SOURCE) ||
399			!Array.isArray(receipt.runs) ||
400			receipt.runs.length !== 4 ||
401			!exact(receipt.placeholders, WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS) ||
402			!exact(receipt.backendCategory, WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY)
403		)
404			throw new Error('Cypress RWA Witness binding differs');
405		for (const run of receipt.runs) {
406			const key = `${run.lane}:${run.pass}`;
407			if (
408				!expectedRuns.delete(key) ||
409				run.app !== REACT_CYPRESS_RWA_APPLICATION ||
410				run.framework !== 'react' ||
411				run.result !== 'pass' ||
412				run.cleanPage !== true ||
413				run.successfulNonLoopback !== 0 ||
414				run.witnessRecord.pageErrors !== 0 ||
415				!Array.isArray(run.interactions) ||
416				run.interactions.length === 0 ||
417				!Array.isArray(run.assertions) ||
418				run.assertions.length === 0 ||
419				!exact(run.routes, WITNESS_REACT_CYPRESS_RWA_ROUTES) ||
420				!exact(run.placeholders, WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS) ||
421				run.semanticDigest !== witnessReactCypressRwaRawDigest(run) ||
422				run.behaviorDigest !== witnessReactCypressRwaBehaviorDigest(run)
423			)
424				throw new Error(`Cypress RWA Witness run differs: ${key}`);
425			assertServedStatic(run.servedStatic, key);
426			assertLoopbackBackend(run.loopbackBackend, key);
427			assertRedaction(run, key);
428			const priorSemantic = semanticByLane.get(run.lane);
429			if (priorSemantic !== undefined && priorSemantic !== run.semanticDigest)
430				throw new Error(`Cypress RWA Witness pass-twice semantic digest differs: ${run.lane}`);
431			semanticByLane.set(run.lane, run.semanticDigest);
432			behaviors.add(run.behaviorDigest);
433		}
434		if (
435			expectedRuns.size !== 0 ||
436			behaviors.size !== 1 ||
437			receipt.determinism?.reseededFromSnapshotBeforeEachPass !== true ||
438			receipt.determinism.mintedValuesPlaceholdered !== true ||
439			receipt.determinism.rule !== WITNESS_JOURNEY_PLACEHOLDER_RULE ||
440			receipt.redaction?.policy !== 'no-seed-usernames-passwords-or-pii' ||
441			receipt.redaction.actorIsNonSeedCorpusIdentity !== true ||
442			!exact(receipt.redaction.forbiddenMarkers, WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS) ||
443			receipt.mutation?.intendedFailure !== true ||
444			receipt.mutation.failure !== 'witness-semantic-assertion' ||
445			receipt.mutation.lane !== 'migrated' ||
446			receipt.mutation.restoredByteIdentically !== true ||
447			receipt.mutation.restoredRun !== 'pass' ||
448			receipt.mutation.beforeSha256 !== receipt.mutation.afterRestoreSha256 ||
449			receipt.mutation.beforeSha256 === receipt.mutation.mutatedSha256 ||
450			!behaviors.has(receipt.mutation.restoredBehaviorDigest) ||
451			receipt.locality?.mode !== 'live-loopback-backend' ||
452			receipt.locality.successfulNonLoopback !== 0 ||
453			receipt.locality.osWideIsolation !== false ||
454			receipt.locality.rule !== WITNESS_LOOPBACK_BACKEND_RULE ||
455			!Array.isArray(receipt.nonclaims) ||
456			receipt.nonclaims.length === 0 ||
457			receipt.integrity?.algorithm !== 'sha256' ||
458			receipt.integrity.canonicalDigest !== witnessReactCypressRwaDigest(receipt)
459		)
460			throw new Error('Cypress RWA Witness integrity or determinism differs');
461		return receipt;
462	}
463	
464	export function witnessReactCypressRwaAggregateMember(digestValue: string) {
465		return {
466			id: 'witness-react-cypress-rwa',
467			framework: 'react',
468			track: 'production-readiness-direct-witness-live-backend-create-react-app-to-vite8',
469			bundler: 'webpack-4.44.2-to-vite-8.0.16',
470			backend: 'live-loopback',
471			result: 'pass',
472			receipt: WITNESS_REACT_CYPRESS_RWA_RECEIPT_PATH,
473			digest: digestValue,
474		};
475	}
