1	import {
2		REACT_CYPRESS_RWA_SOURCE,
3		WITNESS_REACT_CYPRESS_RWA_ACTOR,
4		WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY,
5		WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS,
6	} from '../../../core/src/receipts/witness-react-cypress-rwa.ts';
7	import { buildLoopbackBackendInventory } from './live-backend.ts';
8	import type { AppSpec } from './real-app-run.ts';
9	
10	/**
11	 * The cypress-realworld-app live-backend Witness spec — the corpus's first
12	 * stateful vertical.
13	 *
14	 * The journey is wired straight from the application's own Cypress specs under
15	 * `cypress/tests/ui`, which are the intended exercisable surface: `auth.spec`
16	 * (sign up / sign in), `new-transaction.spec` (send money), `transaction-feeds`
17	 * (public / contacts / personal filters), `notifications` and `user-settings`.
18	 * Every gesture is addressed by the application's own `data-test` attribute, so
19	 * the selectors are the app's, not the harness's. The backend declaration spawns
20	 * the application's REAL Express-over-lowdb server on a second bounded loopback
21	 * origin and re-seeds it from its frozen snapshot before each pass.
22	 *
23	 * Redaction is structural: the journey signs up a fresh, NON-SEED corpus actor
24	 * and acts as it; the one place a seed identity is touched — the recipient of
25	 * the payment — is captured from search and never written literally, it is
26	 * declared as `{recipient-handle}` and normalized away. No seed username,
27	 * password or hash is hard-coded here, and the redaction test enforces it.
28	 *
29	 * This spec is exported for the runner unit to execute; no evidence is published
30	 * from the unit that authored it.
31	 */
32	export function reactCypressRwaWitnessSpec(): AppSpec {
33		const actor = WITNESS_REACT_CYPRESS_RWA_ACTOR;
34		return {
35			app: 'cypress-realworld-app',
36			framework: 'react',
37			canonicalReceipt: 'evidence/runs/react-cypress-rwa/rerun-2026-08-12/build-profile.json',
38			canonicalDigest: '981fbff5b2c8a4e257544bf6ba6abb25334c686fd56605edd6e0a89f4795d1ae',
39			canonicalBinding: 'file-sha256',
40			sources: {
41				baseline: '.versionless/stage/witness-real-app/lanes/cypress-realworld-app/baseline',
42				migrated: '.versionless/stage/witness-real-app/lanes/cypress-realworld-app/migrated',
43			},
44			initialRoute: '/',
45			/**
46			 * The application's own server. Command and port are the app's declared
47			 * ones; the harness copies the frozen seed over the mutable lowdb store and
48			 * runs the app's own prerequisite mock-config copy before boot, then waits
49			 * for the auth-gated `/checkAuth` route to answer — a 401 before any session
50			 * exists is a server that is up.
51			 */
52			backend: {
53				command: 'yarn',
54				args: ['start:api'],
55				cwd: '.',
56				port: 3001,
57				seed: { snapshot: 'data/database-seed.json', store: 'data/database.json' },
58				prepare: [{ from: 'scripts/mock-aws-exports.js', to: 'src/aws-exports.js' }],
59				health: { path: '/checkAuth', okStatus: [401] },
60				readyTimeoutMs: 30_000,
61			},
62			placeholders: WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS,
63			journey: async (context, page, _transportEvidence, lifecycle) => {
64				await page.trackEvents('click', 'input', 'change', 'keydown', 'mouseover');
65	
66				// Auth — sign a fresh non-seed actor up, then sign in as it. No seed
67				// identity is touched here; the credentials are corpus values.
68				await context.expect.page.exists(page, '[data-test=signin-username]');
69				await page.click('[data-test=signup]');
70				await page.type('[data-test=signup-first-name]', actor.firstName);
71				await page.type('[data-test=signup-last-name]', actor.lastName);
72				await page.type('[data-test=signup-username]', actor.username);
73				await page.type('[data-test=signup-password]', actor.password);
74				await page.type('[data-test=signup-confirmPassword]', actor.password);
75				await page.click('[data-test=signup-submit]');
76				await context.expect.page.exists(page, '[data-test=signin-username]');
77				await page.type('[data-test=signin-username]', actor.username);
78				await page.type('[data-test=signin-password]', actor.password);
79				await page.click('[data-test=signin-submit]');
80	
81				// Onboarding — the app's own first-bank-account dialog, then the actor
82				// edits its settings so a mutating write is proven before any transfer.
83				await page.click('[data-test=user-onboarding-next]');
84				await page.type('[data-test=bankaccount-bankName-input]', 'Versionless Bank');
85				await page.type('[data-test=bankaccount-routingNumber-input]', '987654321');
86				await page.type('[data-test=bankaccount-accountNumber-input]', '123456789');
87				await page.click('[data-test=bankaccount-submit]');
88				await page.click('[data-test=user-onboarding-next]');
89				await page.click('[data-test=sidenav-user-settings]');
90				await page.type('[data-test=user-settings-firstName-input]', actor.firstName);
91				await page.click('[data-test=user-settings-submit]');
92	
93				// Money movement — the substantive stateful step. Search a peer, pick the
94				// first result (its handle is captured and normalized, never recorded),
95				// and send a payment the backend mints an id for.
96				await page.click('[data-test=nav-top-new-transaction]');
97				await page.type('[data-test=user-list-search-input]', 'a');
98				await context.expect.page.exists(page, '[data-test^=user-list-item-]');
99				await page.click('[data-test^=user-list-item-]');
100				await page.type('[data-test=transaction-create-amount-input]', '15');
101				await page.type(
102					'[data-test=transaction-create-description-input]',
103					'versionless-proof-payment',
104				);
105				await page.click('[data-test=transaction-create-submit-payment]');
106	
107				// Feed / filter — browse the three feeds the app ships and narrow one.
108				await page.click('[data-test=sidenav-home]');
109				await page.click('[data-test=nav-public-tab]');
110				await page.click('[data-test=nav-contacts-tab]');
111				await page.click('[data-test=nav-personal-tab]');
112				await page.click('[data-test=transaction-list-filter-amount-range-button]');
113	
114				// Notifications — read the app's own notification feed.
115				await page.click('[data-test=sidenav-notifications]');
116	
117				await context.expect.page.outcome(page, {
118					events: {
119						click: { atLeast: 12 },
120						input: { atLeast: 8 },
121						keydown: { atLeast: 8 },
122					},
123				});
124	
125				// The loopback-backend inventory, built generically from the run's own
126				// request ledger against the two bounded loopback origins.
127				const loopbackBackend =
128					lifecycle.requestOutcomes === undefined ||
129					lifecycle.backendOrigin === undefined ||
130					lifecycle.staticOrigin === undefined
131						? undefined
132						: buildLoopbackBackendInventory(
133								lifecycle.requestOutcomes(),
134								lifecycle.staticOrigin,
135								lifecycle.backendOrigin,
136								WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY,
137							);
138	
139				return {
140					assertions: [
141						'sign up and sign in as a fresh non-seed actor',
142						'onboarding first bank account and settings write',
143						'money movement to a placeholdered peer',
144						'public / contacts / personal feeds with a filter',
145						'notifications feed',
146						'clean page',
147					],
148					offlineEvidence: { state: 'not-applicable' },
149					...(loopbackBackend === undefined
150						? {}
151						: {
152								applicationJourney: {
153									state: 'live-loopback-backend-journey',
154									source: REACT_CYPRESS_RWA_SOURCE.revision,
155									loopbackBackend,
156								},
157							}),
158				};
159			},
160		};
161	}
